INSERT INTO lp_task_templates (key, title, description, why, benefit, steps, safety_note, task_type, frequency, assignee, subject, min_day, max_day, estimated_minutes, xp, emoji, category_key, resource_slug, source_key, sex, review_status, sort_order) VALUES
  ('fd_three_questions', '{"en":"Ask three questions about their day","bn":"সন্তানের দিন নিয়ে তিনটি প্রশ্ন করুন"}'::jsonb, '{"en":"Instead of “How was school?”, ask three specific questions and really listen.","bn":"“স্কুল কেমন ছিল?” না বলে নির্দিষ্ট তিনটি প্রশ্ন করুন, আর মন দিয়ে শুনুন।"}'::jsonb, '{"en":"Specific questions get real answers. Listening every day shows your child that their world matters, and makes it easier for them to tell you when something is wrong.","bn":"নির্দিষ্ট প্রশ্নে সত্যিকারের উত্তর মেলে। প্রতিদিন মন দিয়ে শুনলে সন্তান বোঝে তার জগৎ আপনার কাছে গুরুত্বপূর্ণ, আর কিছু ভুল হলে আপনাকে বলা সহজ হয়।"}'::jsonb, '{"en":"A closer bond and an early sign of any problems at school.","bn":"গভীর সম্পর্ক, আর স্কুলের কোনো সমস্যার আগাম খোঁজ।"}'::jsonb, '[{"en":"Choose a calm moment: the walk home, tiffin time or bedtime.","bn":"শান্ত একটা সময় বাছুন: বাসায় ফেরার পথ, বিকেলের নাশতা বা ঘুমের আগে।"},{"en":"Ask, for example: “What made you laugh today? Who did you play with? Was anything hard?”","bn":"যেমন জিজ্ঞেস করুন: “আজ কোন কথায় হেসেছ? কার সাথে খেলেছ? কিছু কঠিন লেগেছে?”"},{"en":"Listen without correcting, and share something about your own day.","bn":"ভুল না ধরে শুনুন, আর নিজের দিনের একটা কথাও বলুন।"}]'::jsonb, '{}'::jsonb, 'family', 'daily', 'shared', 'child', 1461, 2557, 10, 10, '💬', 'emotions', 'fd-father-school-life', 'unicef_parenting', 'any', 'in_review'::lp_review_status, 6101),
  ('fd_pack_bag_night', '{"en":"Pack the school bag the night before","bn":"আগের রাতে স্কুলব্যাগ গুছিয়ে রাখুন"}'::jsonb, '{}'::jsonb, '{"en":"Packing the bag with your child, and later by themselves, builds independence and responsibility, and makes school mornings calmer for everyone.","bn":"সন্তানের সাথে মিলে, পরে সে নিজেই ব্যাগ গোছালে স্বাবলম্বিতা আর দায়িত্ববোধ বাড়ে, আর স্কুলের সকালগুলো সবার জন্য শান্ত হয়।"}'::jsonb, '{"en":"Fewer rushed, tearful mornings and a more confident child.","bn":"তাড়াহুড়ো আর কান্নার সকাল কমে, সন্তান হয় আরও আত্মবিশ্বাসী।"}'::jsonb, '[{"en":"Use a simple picture list on the wall: books, copybook, pencil box, water bottle.","bn":"দেয়ালে ছবিসহ ছোট একটা তালিকা রাখুন: বই, খাতা, পেনসিল বক্স, পানির বোতল।"},{"en":"Let your child pack while you check; step back as they get better.","bn":"সন্তান গোছাবে, আপনি দেখে দেবেন; সে যত দক্ষ হবে, আপনি তত পিছিয়ে আসবেন।"},{"en":"Put out tomorrow''s uniform and shoes together.","bn":"পরদিনের ইউনিফর্ম আর জুতা একসাথে বের করে রাখুন।"}]'::jsonb, '{}'::jsonb, 'recommended', 'daily', 'any', 'child', 1461, 2557, 10, 5, '🎒', 'development', 'fd-confidence-independence', NULL, 'any', 'in_review'::lp_review_status, 6102),
  ('fd_body_safety_talk', '{"en":"Have a short, calm body-safety talk","bn":"শরীরের নিরাপত্তা নিয়ে ছোট, শান্ত একটা আলাপ করুন"}'::jsonb, '{}'::jsonb, '{"en":"Children who know the names of their body parts, the “No, Go, Tell” rule and who their trusted adults are find it easier to speak up. Short, repeated talks work better than one big talk.","bn":"যে শিশু শরীরের অঙ্গের নাম, “না বলো, চলে যাও, জানাও” নিয়ম আর বিশ্বস্ত বড়দের চেনে, তার পক্ষে মুখ খোলা সহজ হয়। একবারের বড় আলোচনার চেয়ে বারবার ছোট আলাপ বেশি কাজ করে।"}'::jsonb, '{"en":"Better protection, and a child who knows they can tell you anything.","bn":"ভালো সুরক্ষা, আর এমন সন্তান যে জানে, আপনাকে সব বলা যায়।"}'::jsonb, '[{"en":"Pick a relaxed moment, such as bath time or a walk.","bn":"নিশ্চিন্ত একটা সময় বাছুন, যেমন গোসল বা হাঁটার সময়।"},{"en":"Go over one idea: private parts, “No, Go, Tell”, safe and unsafe secrets, or trusted adults.","bn":"একটা বিষয় নিয়ে কথা বলুন: গোপন অঙ্গ, “না বলো, চলে যাও, জানাও”, ভালো আর খারাপ গোপন কথা, বা বিশ্বস্ত বড়রা।"},{"en":"End with: “You can always tell me, and you will never be in trouble for telling.”","bn":"শেষে বলুন: “তুমি আমাকে সবসময় বলতে পারো, বললে কখনো বকা খাবে না।”"}]'::jsonb, '{"en":"If your child tells you about abuse, stay calm, believe them and keep them safe. In Bangladesh, call the Child Helpline 1098, or 999 in an emergency.","bn":"সন্তান কোনো নির্যাতনের কথা বললে শান্ত থাকুন, বিশ্বাস করুন আর তাকে নিরাপদে রাখুন। বাংলাদেশে চাইল্ড হেল্পলাইন ১০৯৮, জরুরি অবস্থায় ৯৯৯-এ ফোন করুন।"}'::jsonb, 'learn', 'monthly', 'shared', 'child', 1461, 2557, 10, 15, '🛡️', 'safety', 'fd-body-safety', 'who_inspire', 'any', 'in_review'::lp_review_status, 6103),
  ('fd_eye_check_school', '{"en":"Get an eye check before school","bn":"স্কুলের আগে চোখ পরীক্ষা করান"}'::jsonb, '{}'::jsonb, '{"en":"Children rarely say they cannot see well. Some eye problems, such as a lazy eye, are easiest to treat when found early.","bn":"শিশুরা খুব কমই বলে যে ঠিকমতো দেখতে পাচ্ছে না। অলস চোখের মতো কিছু সমস্যা আগে ধরা পড়লে চিকিৎসা সবচেয়ে সহজ।"}'::jsonb, '{"en":"Your child can see the board and the book clearly from day one.","bn":"প্রথম দিন থেকেই সন্তান বোর্ড আর বই স্পষ্ট দেখতে পায়।"}'::jsonb, '[{"en":"Book a check with your doctor, an eye hospital or the Upazila Health Complex.","bn":"ডাক্তার, চক্ষু হাসপাতাল বা উপজেলা স্বাস্থ্য কমপ্লেক্সে পরীক্ষার ব্যবস্থা করুন।"},{"en":"Tell them about any squint, head tilting, sitting close to the TV or headaches.","bn":"ট্যারা, মাথা কাত করে দেখা, টিভির কাছে বসা বা মাথাব্যথা থাকলে জানান।"},{"en":"Mention hearing too if you have any worry.","bn":"শোনা নিয়ে কোনো দুশ্চিন্তা থাকলে তাও বলুন।"}]'::jsonb, '{}'::jsonb, 'must_do', 'once', 'shared', 'child', 1461, 2557, 60, 25, '👁️', 'medical_care', 'fd-vision-hearing-checks', 'aap_healthychildren', 'any', 'in_review'::lp_review_status, 6104),
  ('fd_own_chore', '{"en":"Let your child do one small chore of their own","bn":"সন্তানকে নিজের একটা ছোট কাজ করতে দিন"}'::jsonb, '{}'::jsonb, '{"en":"A small daily job, like watering plants or setting spoons, teaches responsibility and shows your child they are a useful part of the family.","bn":"গাছে পানি দেওয়া বা চামচ সাজানোর মতো ছোট একটা প্রতিদিনের কাজ দায়িত্ববোধ শেখায়, আর সন্তান বোঝে পরিবারে তার কাজের দাম আছে।"}'::jsonb, '{"en":"Confidence, responsibility and a little help for the family.","bn":"আত্মবিশ্বাস, দায়িত্ববোধ আর পরিবারের জন্য একটু সাহায্য।"}'::jsonb, '[]'::jsonb, '{"en":"No stove, sharp knives, hot water, chemicals or electrical sockets at this age.","bn":"এই বয়সে চুলা, ধারালো বঁটি-ছুরি, গরম পানি, রাসায়নিক বা বিদ্যুতের সকেট নয়।"}'::jsonb, 'recommended', 'daily', 'any', 'child', 1461, 2557, 5, 5, '🧺', 'character', 'fd-chores-by-age', NULL, 'any', 'in_review'::lp_review_status, 6105),
  ('fd_name_writing', '{"en":"Practise writing their name, in a playful way","bn":"খেলার ছলে নিজের নাম লেখার অনুশীলন"}'::jsonb, '{}'::jsonb, '{"en":"Writing their own name is a proud first step in writing. A few relaxed minutes a week, in sand, with chalk or on paper, builds the skill without stress.","bn":"নিজের নাম লেখা লেখালেখির গর্বের প্রথম ধাপ। সপ্তাহে কয়েক মিনিট বালুতে, চক দিয়ে বা কাগজে নিশ্চিন্ত অনুশীলনে চাপ ছাড়াই দক্ষতা তৈরি হয়।"}'::jsonb, '{"en":"Stronger hands, letter recognition and pride in learning.","bn":"হাত শক্ত হয়, বর্ণ চেনা বাড়ে, শেখায় গর্ব জাগে।"}'::jsonb, '[{"en":"Write the name in big letters for your child to trace or copy.","bn":"বড় বড় অক্ষরে নামটা লিখে দিন, সন্তান ওপর দিয়ে বুলাবে বা দেখে লিখবে।"},{"en":"Try different materials: a finger in rice, chalk on the floor, a crayon on paper.","bn":"নানা জিনিস দিয়ে চেষ্টা করুন: চালে আঙুল দিয়ে, মেঝেতে চক দিয়ে, কাগজে রং-পেনসিল দিয়ে।"},{"en":"Stop after a few minutes while it is still fun, and praise the effort.","bn":"মজা থাকতে থাকতে কয়েক মিনিট পর থামুন, আর চেষ্টার প্রশংসা করুন।"}]'::jsonb, '{}'::jsonb, 'learn', 'weekly', 'shared', 'child', 1826, 2557, 10, 10, '✏️', 'early_education', 'fd-letters-numbers-play', NULL, 'any', 'in_review'::lp_review_status, 6106),
  ('fd_praise_effort', '{"en":"Praise effort, not just results","bn":"শুধু ফলাফল নয়, চেষ্টার প্রশংসা করুন"}'::jsonb, '{}'::jsonb, '{"en":"Saying “You kept trying” rather than only “You are so clever” teaches children that effort leads to progress, so they are more willing to try hard things.","bn":"শুধু “তুমি খুব বুদ্ধিমান” না বলে “তুমি হাল ছাড়োনি” বললে শিশু শেখে যে চেষ্টায় উন্নতি হয়, ফলে কঠিন কাজেও সে চেষ্টা করতে আগ্রহী হয়।"}'::jsonb, '{"en":"A child who keeps going when things are hard, and better behaviour.","bn":"কঠিন সময়েও হাল না ছাড়া সন্তান, আর ভালো আচরণ।"}'::jsonb, '[{"en":"Notice one moment today when your child tried hard, helped or was kind.","bn":"আজ সন্তান যখন খুব চেষ্টা করেছে, সাহায্য করেছে বা সুন্দর আচরণ করেছে, এমন একটা মুহূর্ত খেয়াল করুন।"},{"en":"Name exactly what they did: “You did all your buttons yourself.”","bn":"ঠিক কী করেছে বলুন: “সব বোতাম তুমি নিজে লাগিয়েছ।”"}]'::jsonb, '{}'::jsonb, 'recommended', 'daily', 'shared', 'child', 1461, 2557, 2, 5, '🌟', 'positive_discipline', 'fd-positive-discipline', 'cdc_positive_parenting', 'any', 'in_review'::lp_review_status, 6107),
  ('fd_family_walk_game', '{"en":"Go for a family walk or play an active game together","bn":"পরিবারের সবাই মিলে হাঁটুন বা ছোটাছুটির খেলা খেলুন"}'::jsonb, '{}'::jsonb, '{"en":"Children need plenty of active play, and moving together is fun, good for everyone''s health and a time to talk away from screens.","bn":"শিশুর অনেক খেলাধুলা দরকার, আর সবাই মিলে নড়াচড়া মজার, সবার স্বাস্থ্যের জন্য ভালো, আর স্ক্রিন থেকে দূরে গল্প করার সময়।"}'::jsonb, '{"en":"More activity, better sleep and happy family memories.","bn":"বেশি নড়াচড়া, ভালো ঘুম আর পরিবারের সুন্দর স্মৃতি।"}'::jsonb, '[{"en":"Pick a time this week when most of the family is free.","bn":"এ সপ্তাহে পরিবারের বেশিরভাগ সদস্য অবসর এমন একটা সময় বাছুন।"},{"en":"Walk to a park or field, or play gollachut, kanamachi, football or badminton.","bn":"পার্ক বা মাঠে হেঁটে যান, অথবা গোল্লাছুট, কানামাছি, ফুটবল বা ব্যাডমিন্টন খেলুন।"},{"en":"Leave phones in pockets and let your child choose the game sometimes.","bn":"মোবাইল পকেটে রাখুন, আর মাঝে মাঝে খেলা বাছাইয়ের ভার সন্তানকে দিন।"}]'::jsonb, '{"en":"Keep away from roads and open water, and avoid the hottest part of the day.","bn":"রাস্তা আর খোলা পানি থেকে দূরে থাকুন, আর দিনের সবচেয়ে গরম সময় এড়িয়ে চলুন।"}'::jsonb, 'family', 'weekly', 'any', 'family', 1461, 2557, 45, 15, '🚶', 'physical_activity', 'fd-moving-every-day', 'who_activity_5_17', 'any', 'in_review'::lp_review_status, 6108)
